export interface PricingRule {
  id: string;
  /** "case_fee", "recovery_commission" ou "study_fee". */
  object: string;
  /**
   * "fixed", "percentage", "tiered" ou "by_stage". "tiered" : pour la commission, calcul progressif
   * sur le cumul encaissé du dossier (chaque part au taux de sa tranche, la commission d'un
   * encaissement est celle du cumul après lui moins celle du cumul avant lui) ; pour les frais de
   * dossier, montant fixe de la tranche où tombe le montant dû (ADR-062). Une règle "tiered" porte soit des taux (rate_bps), soit des montants (fixed_amount), le même
   * choix pour toutes ses tranches. Modes admis par objet : case_fee "fixed" ou "tiered" en
   * montants ; study_fee "fixed" ; recovery_commission "fixed", "percentage", "tiered" en taux ou
   * "by_stage" (RECOVERY_PRICING_RULE_INVALID sinon).
   */
  mode: string;
  fixedAmount?:
    | Money
    | undefined;
  /** Taux du mode "percentage" ; -1 = absent (autres modes). */
  rateBps: number;
  tiers: PricingTier[];
  stageRates: StageRate[];
  /**
   * Bornes facultatives (absentes = sans borne). Commission : maximum par encaissement, minimum au
   * cumul du dossier (complété sur les encaissements suivants). Frais et forfait : montant calculé.
   */
  minimum?: Money | undefined;
  maximum?: Money | undefined;
  target?: PricingTarget | undefined;
  validFrom: string;
  validUntil: string;
  version: number;
  /** "draft", "pending_approval", "published", "archived". */
  status: string;
  label: string;
  createdBy?: Actor | undefined;
  approvedBy?: Actor | undefined;
  publishedAt: string;
  /** Règle dont celle-ci est la nouvelle version, vide pour une première version. */
  previousVersionId: string;
}

export interface PricingRuleInput {
  object: string;
  mode: string;
  fixedAmount?: Money | undefined;
  rateBps: number;
  tiers: PricingTier[];
  stageRates: StageRate[];
  /** Bornes facultatives, comme PricingRule.minimum et maximum. */
  minimum?: Money | undefined;
  maximum?: Money | undefined;
  target?: PricingTarget | undefined;
  validFrom: string;
  validUntil: string;
  label: string;
  /** Nouvelle version d'une règle publiée, vide pour une nouvelle règle. */
  previousVersionId: string;
}

